mapper.select:
SELECT pt.id as taskId, ptd.sku_id, ptd.sku_no, ptd.fn_sku, SUM(ptd.delivery_qty) as deliveryQty FROM packing_task pt LEFT JOIN packing_task_detail ptd ON pt.id = ptd.main_id AND ptd.is_deleted = FALSE where pt.is_deleted = FALSE and pt.id in
#{id}
GROUP BY pt.id, ptd.sku_id, ptd.sku_no, ptd.fn_sku
